use serde_json::{Value, json};
pub(crate) fn schemas() -> Vec<Value> {
    let string = json!({"type":"string"});
    [
        ("memory_search","Search your own accessible history across conversations, or your private source-backed notes. Use when current context lacks earlier decisions or external-chat information; do not guess. kind=messages (default) searches original text; kind=notes searches topic/summary. day is UTC YYYY-MM-DD; since/until are Unix milliseconds for local-date ranges. Dates on notes filter original source dates. before is the previous next_cursor; keep filters unchanged. Bounded scans may return empty items with a cursor: continue until next_cursor is null. Never exposes others' private chats; retrieval does not grant permission to publish private information.",json!({"query":{"type":"string","maxLength":256},"kind":{"enum":["messages","notes"]},"conversation":string,"day":string,"since":{"type":"integer"},"until":{"type":"integer"},"before":{"type":"integer"},"limit":{"type":"integer","minimum":1,"maximum":50}}),vec![]),
        ("memory_save","Save a private topic/summary for your fixed identity with 1..32 visible source message IDs. Use to remember decisions, useful facts and progress across chats; never store credentials or other people's hidden state. id is your stable note key; expected_revision=0 creates, otherwise update the revision returned by memory_read/search. Source access is checked on every retrieval; deleted sources hide the note. A summary is not authoritative game/task state. This does not share memory with teammates.",json!({"id":{"type":"string","minLength":1,"maxLength":128},"topic":{"type":"string","minLength":1,"maxLength":120},"summary":{"type":"string","minLength":1,"maxLength":4000},"source_messages":{"type":"array","items":string,"minItems":1,"maxItems":32},"expected_revision":{"type":"integer","minimum":0}}),vec!["id","topic","summary","source_messages","expected_revision"]),
        ("memory_read","Read your private note and its currently visible original source messages. Source deletion or lost visibility prevents recall. Recheck evidence before using an old summary.",json!({"id":string}),vec!["id"]),
        ("memory_forget","Delete your private note using its current revision; original chat messages remain searchable. This is not conversation reset or message deletion.",json!({"id":string,"expected_revision":{"type":"integer"}}),vec!["id","expected_revision"]),
    ].into_iter().map(|(name,description,properties,required)|json!({"name":name,"description":description,"inputSchema":{"type":"object","properties":properties,"required":required,"additionalProperties":false}})).collect()
}
